/// <summary>
/// Class created to return version information from the model.
/// </summary>
class TFMVersion
{
    str versionStr;
    str Publisher;
    str versionName;
    #tfm
    #define.modelClass(Microsoft.Dynamics.AX.Metadata.MetaModel.ModelInfo)

}

Method.Source:
public static TFMVersion Construct()
{
    return new TFMVersion();
}

protected void new()
{
    #ifnot.isAX6
    Microsoft.Dynamics.AX.Metadata.MetaModel.ModelInfo modelInfo = TFMVersion::modelForClass(classIdGet(this));
    versionStr = strFmt('%1.%2.%3.%4', modelInfo.VersionMajor, modelInfo.VersionMinor, modelInfo.VersionBuild, modelInfo.VersionRevision);
    Publisher = modelInfo.Publisher;
    versionName = modelInfo.Description;
    #endif
    #if.isAX6
    #AOT
    TreeNode            node = TreeNode::findNode(#ClassesPath+ '\\' + classStr(TFMVersion));
    XML                 manifest = SysModelStore::getModelManifest(int642int(node.AOTGetModel()));
    XmlDocument         document = XmlDocument::newXml(manifest);
    XmlElement          elementModelManifest;
    XmlElement          elementVersion;
    str                 ret = "@RET1644";
    elementModelManifest = document.getNamedElement('ModelManifest');
    if (elementModelManifest)
    {
        elementVersion = elementModelManifest.getNamedElement('Version');
        if (elementVersion)
        {
            versionStr = elementVersion.text();
        }
    }

    //versionStr = strFmt('%1.%2.%3.%4', modelInfo.VersionMajor, modelInfo.VersionMinor, modelInfo.VersionBuild, modelInfo.VersionRevision);
    Publisher = 'Tasklet Factory';
    versionName = 'Obelisk';

    #endif
}

/// <summary>
/// A method to retrieve the model that a certain class belongs to.
/// </summary>
/// <param name = "_classID">The Class ID of the class, you need to know the model for.</param>
/// <returns>Model Info of the model that contains the class.</returns>
public static #modelClass modelForClass(ClassId _classID)
{   
    #ifnot.isAX6
    var models = Microsoft.Dynamics.Ax.Xpp.MetadataSupport::GetModelsOfMetadataArtifact(classId2Name(_classID), new Microsoft.Dynamics.AX.Metadata.MetaModel.AxClass().GetType());
    var Enumerator = models.getEnumerator();
    Enumerator.moveNext();
    Microsoft.Dynamics.AX.Metadata.MetaModel.ModelInfo modelInfo = Enumerator.Current;
    return modelInfo;
    #endif
    #if.isAX6
    return '';
    #endif
}

/// <summary>
/// Method used to populate a FormGroupControl of a form, with the models that extend mobile WMS.
/// </summary>
/// <param name = "_fgc">The FormGroupControl to populate with the model names.</param>
public void populateGroupWithExtensions(FormGroupControl _fgc)
{
    MapEnumerator           extensionModels = TFMVersion::extensionModels().getEnumerator();
    FormStaticTextControl   fstc;
    while (extensionModels.moveNext())
    {
        fstc = _fgc.addControl(FormControlType::StaticText,guid2Str(newGuid()));
        fstc.text(extensionModels.currentValue());
    }
}

/// <summary>
/// A method to find all the Document Handler Classes, and check if any of them are in a model different from the main Mobile WMS Model.
/// </summary>
/// <returns>A Map containing all the models with document handlers, that are not in the main Mobile WMS model.</returns>
public static Map extensionModels()
{
    Map                                                 modelsInstalled = new Map ( Types::String, Types::String);
    #ifnot.isAX6
    ListEnumerator                                      lEnum           = new DictClass(className2Id(classStr(TFMDocumentHandler))).extendedBy(true).getEnumerator();
    Microsoft.Dynamics.AX.Metadata.MetaModel.ModelInfo  modelInfo = TFMVersion::modelForClass(className2Id(classStr(TFMDocumentHandler)));
    int                                                 modelIgnoreID = modelInfo.Id;

    while (lEnum.moveNext())
    {            
        modelInfo = TFMVersion::modelForClass(lEnum.current());
        if ( modelsInstalled.exists(modelInfo.Id) || modelInfo.Id == modelIgnoreID)
        {
            continue;
        }
        modelsInstalled.insert(modelInfo.Name,strFmt('%1 %2 %3.%4.%5.%6 %7 %8',modelInfo.DisplayName, "@SYS40796", modelInfo.VersionMajor, modelInfo.VersionMinor, modelInfo.VersionBuild, modelInfo.VersionRevision,"@SYS190924",modelInfo.Publisher));
    }

    #endif


    return modelsInstalled;
}
